{
  "explanation": "A cone and a cylinder with the same base radius R and height H have cross-sectional areas that behave very differently. The cylinder’s slice is always πR², while the cone’s radius shrinks linearly from the base, so its slice area shrinks as the square of the remaining height. Integrating those areas from base to tip gives V_cone = ∫ πR²(h/H)² dh = (1/3)πR²H — exactly one-third the cylinder’s volume.",
  "manimCode": "const title = new MathTex({ latex: 'V_{\\text{cone}} = \\tfrac{1}{3} V_{\\text{cylinder}}' });
await title.waitForRender();
title.moveTo([0, 3.5, 0]);
title.scale(0.85);
scene.add(title);

const H = 3.2;
const R = 1.1;
const baseY = -2.4;

// --- Cylinder (left) ---
const cylX = -4.2;
const cyl = new Rectangle({ width: 2 * R, height: H, color: BLUE });
cyl.moveTo([cylX, baseY + H / 2, 0]);
cyl.setFill(BLUE, 0.15).setStrokeWidth(2);
scene.add(cyl);

const cylTop = new Polygon({
  vertices: [[cylX - R, baseY + H, 0], [cylX + R, baseY + H, 0]],
  color: BLUE
});
cylTop.setStrokeWidth(2).setFillOpacity(0);
scene.add(cylTop);

const cylLabel = new Text({ text: 'Cylinder', color: BLUE, fontSize: 22 });
cylLabel.moveTo([cylX, baseY - 0.45, 0]);
scene.add(cylLabel);

// --- Cone (middle) ---
const coneX = -1.2;
const cone = new Polygon({
  vertices: [
    [coneX - R, baseY, 0],
    [coneX + R, baseY, 0],
    [coneX, baseY + H, 0]
  ],
  color: ORANGE
});
cone.setFill(ORANGE, 0.15).setStrokeWidth(2);
scene.add(cone);

const coneLabel = new Text({ text: 'Cone', color: ORANGE, fontSize: 22 });
coneLabel.moveTo([coneX, baseY - 0.45, 0]);
scene.add(coneLabel);

// Shared base & height markers
const baseLine = new Line({ start: [cylX - R - 0.15, baseY, 0], end: [coneX + R + 0.15, baseY, 0], color: GRAY });
baseLine.setStrokeWidth(1);
scene.add(baseLine);

const hBrace = new Line({ start: [coneX + R + 0.35, baseY, 0], end: [coneX + R + 0.35, baseY + H, 0], color: GRAY });
hBrace.setStrokeWidth(1.5);
scene.add(hBrace);
const hLabel = new MathTex({ latex: 'H' });
await hLabel.waitForRender();
hLabel.scale(0.55);
hLabel.nextTo(hBrace, RIGHT);
hLabel.shift(scaleVec(0.1, LEFT));
scene.add(hLabel);

// --- Cross-section area graph (right) ---
const ax = new Axes({
  xRange: [0, 1, 0.25],
  yRange: [0, 1.15, 0.25],
  xLength: 4.2,
  yLength: 3.4,
  tips: false
});
ax.moveTo([3.3, 0.1, 0]);
scene.add(ax);

const xLbl = new Text({ text: 'height fraction t', color: GRAY, fontSize: 16 });
xLbl.moveTo([3.3, -2.0, 0]);
scene.add(xLbl);
const yLbl = new Text({ text: 'A / (πR²)', color: GRAY, fontSize: 16 });
yLbl.moveTo([0.7, 0.1, 0]);
scene.add(yLbl);

// Cylinder area = 1 (flat)
const cylGraph = ax.plot(() => 1, { color: BLUE, xRange: [0, 1] });
cylGraph.setStrokeWidth(3);
scene.add(cylGraph);

// Cone area = t²  (t = 0 at apex, t = 1 at base)
const coneGraph = ax.plot(t => t * t, { color: ORANGE, xRange: [0, 1], numSamples: 80 });
coneGraph.setStrokeWidth(3);
scene.add(coneGraph);

// Shaded region under cone curve (full integral = 1/3)
const shade = ax.getArea(coneGraph, [0, 1], { color: ORANGE, opacity: 0.25 });
scene.add(shade);

const thirdLabel = new MathTex({ latex: '\\int_0^1 t^2\\,dt = \\tfrac{1}{3}' });
await thirdLabel.waitForRender();
thirdLabel.scale(0.5);
thirdLabel.moveTo([3.3, 2.55, 0]);
scene.add(thirdLabel);

// --- Interactive slice ---
let t = 0.65; // fraction from apex (0=apex, 1=base)

// Horizontal slice lines on the solids
function sliceY(tt) {
  return baseY + H * (1 - tt); // apex at top
}
function coneR(tt) {
  return R * tt;
}

let sliceCyl = new Polygon({
  vertices: [[cylX - R, sliceY(t), 0], [cylX + R, sliceY(t), 0]],
  color: YELLOW
});
sliceCyl.setStrokeWidth(3).setFillOpacity(0);
scene.add(sliceCyl);

let sliceCone = new Polygon({
  vertices: [[coneX - coneR(t), sliceY(t), 0], [coneX + coneR(t), sliceY(t), 0]],
  color: YELLOW
});
sliceCone.setStrokeWidth(3).setFillOpacity(0);
scene.add(sliceCone);

// Tiny cross-section "disks" (ellipses approximated as flattened circles via polygons)
function makeDisk(cx, cy, rx, color) {
  const n = 24;
  const verts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    verts.push([cx + rx * Math.cos(a), cy + rx * 0.28 * Math.sin(a), 0]);
  }
  const p = new Polygon({ vertices: verts, color });
  p.setFill(color, 0.45).setStrokeWidth(1.5);
  return p;
}

let diskCyl = makeDisk(cylX, sliceY(t), R, BLUE);
let diskCone = makeDisk(coneX, sliceY(t), coneR(t), ORANGE);
scene.add(diskCyl, diskCone);

// Marker on the graph
let graphDotCyl = new Dot({ point: ax.c2p(t, 1), color: BLUE });
let graphDotCone = new Dot({ point: ax.c2p(t, t * t), color: ORANGE });
scene.add(graphDotCyl, graphDotCone);

let areaReadout = new Text({
  text: 'A_cone / A_cyl = ' + (t * t).toFixed(2),
  color: WHITE,
  fontSize: 20
});
areaReadout.moveTo([3.3, -2.55, 0]);
scene.add(areaReadout);

function refresh(tt) {
  t = tt;
  const y = sliceY(t);
  const cr = coneR(t);

  sliceCyl.setVertices([[cylX - R, y, 0], [cylX + R, y, 0]]);
  sliceCone.setVertices([[coneX - cr, y, 0], [coneX + cr, y, 0]]);

  scene.remove(diskCyl);
  scene.remove(diskCone);
  diskCyl = makeDisk(cylX, y, R, BLUE);
  diskCone = makeDisk(coneX, y, cr, ORANGE);
  scene.add(diskCyl, diskCone);

  graphDotCyl.moveTo(ax.c2p(t, 1));
  graphDotCone.moveTo(ax.c2p(t, t * t));

  const pos = areaReadout.getCenter();
  scene.remove(areaReadout);
  areaReadout = new Text({
    text: 'A_cone / A_cyl = ' + (t * t).toFixed(2) + '  (= t²)',
    color: WHITE,
    fontSize: 20
  });
  areaReadout.moveTo(pos);
  scene.add(areaReadout);
}

// Legend
const legCyl = new Text({ text: '— cylinder (constant)', color: BLUE, fontSize: 16 });
legCyl.moveTo([-4.2, 3.0, 0]);
scene.add(legCyl);
const legCone = new Text({ text: '— cone (∝ t²)', color: ORANGE, fontSize: 16 });
legCone.moveTo([-1.2, 3.0, 0]);
scene.add(legCone);

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({
  label: 'Slice t (0=apex → 1=base)',
  min: 0.02,
  max: 1,
  value: t,
  step: 0.01,
  onChange: (v) => refresh(v)
});
controls.addButton({
  label: 'Reset',
  onClick: () => refresh(0.65)
});

await scene.wait(999999);"
}

